def _get_numbers_distance(num1, num2, max_=1, use_log_scale=False,
    log_scale_similarity_threshold=0.1):
    if num1 == num2:
        return 0
    if use_log_scale:
        log_num1 = math.copysign(math.log(abs(num1) + MATH_LOG_OFFSET), num1)
        log_num2 = math.copysign(math.log(abs(num2) + MATH_LOG_OFFSET), num2)
        num1 = log_num1
        num2 = log_num2
    divisor = (num1 + num2) / max_
    if divisor == 0:
        return max_
    result = abs((num1 - num2) / divisor)
    distance = min(result, max_)
    if use_log_scale and distance < log_scale_similarity_threshold:
        return 0
    return distance

def _get_date_distance(date1, date2, max_, use_log_scale,
    log_scale_similarity_threshold):
    return _get_numbers_distance(
        date1.toordinal(), date2.toordinal(), max_, use_log_scale, log_scale_similarity_threshold)
